try { const saved = JSON.parse(localStorage.getItem('portbridge-ui-commands') || 'null'); if(Array.isArray(saved) && saved.length && saved.every(c => typeof c.name === 'string' && typeof c.payload === 'string' && ['hex','text'].includes(c.format))) commands = saved.slice(0,30); } catch {}
let activeId = 'udp', page = 'workspace', view = 'data', displayFormat = 'hex', inspector = 'bytes', scenario = 'normal';
