function renderBanner(){let message='';if(!current().connected)message='连接未启动。检查左侧参数后连接，发送和记录将在连接后可用。';else if(scenario==='overload')message='模拟接收过载：应用队列丢弃 2,048 报文。原始记录可能不完整，请查看丢失诊断。';else if(scenario==='disk')message=recording?'模拟记录变慢：写入 180 MB/s，低于接收速率，记录队列正在积压。':'模拟磁盘场景：启动记录后将展示写入不足与队列积压。';else if(pause)message=`显示已暂停，接收与记录继续；期间未展示 ${number(pauseSkipped)} 条模拟样本。`;
  $('#state-banner').textContent=message;$('#state-banner').hidden=!message;
}
function displayed(){return pause?pauseSnapshot:records;}
function renderRecords(){
  const filter=$('#record-filter').value.trim().toLowerCase();const shown=displayed().filter(r=>!filter||r.peer.toLowerCase().includes(filter)||hex(r.bytes).toLowerCase().includes(filter)||text(r.bytes).toLowerCase().includes(filter));
  $('#record-body').innerHTML=shown.map(r=>`<tr data-record="${r.id}" tabindex="0" aria-selected="${r.id===selectedId}" class="${r.id===selectedId?'selected':''}"><td>${String(r.id).padStart(3,'0')}</td><td>${esc(r.time)}</td><td><span class="direction ${r.direction==='TX'?'tx':''}">${r.direction}</span></td><td>${esc(r.peer)}</td><td>${number(r.length)}</td><td class="preview-cell">${esc(displayFormat==='hex'?hex(r.bytes.slice(0,16)):text(r.bytes.slice(0,32)))}${r.bytes.length>16?' …':''}</td></tr>`).join('');
  $('#record-empty').hidden=shown.length!==0;$('#sample-count').textContent=displayed().length;$('#record-footer-count').textContent=`显示 ${shown.length} / ${displayed().length} 条${current().mode==='high'?'样本':'记录'}`;
  if(!pause && $('#auto-scroll').checked && $('#record-body').children.length && selectedId!==records[0]?.id){const scroll=$('.table-scroll');scroll.scrollTop=scroll.scrollHeight;}
  renderBytes();
}
function renderBytes(){
  const record=displayed().find(r=>r.id===selectedId)||displayed()[0];
  if(!record){$('#byte-inspector').innerHTML='<div class="empty-state"><strong>未选择数据</strong><p>选择一条记录检查原始字节。</p></div>';return;}
  const bytes=record.bytes.slice(0,32),rows=[];for(let i=0;i<bytes.length;i+=8)rows.push(`<div><span class="offset">${i.toString(16).padStart(4,'0')}</span>${[...bytes.slice(i,i+8)].map((b,j)=>`<span class="${i+j<4?'marked':''}">${b.toString(16).padStart(2,'0').toUpperCase()}</span>`).join(' ')}</div>`);
  $('#byte-inspector').innerHTML=`<div class="inspector-section"><div class="eyebrow">RECORD ${String(record.id).padStart(3,'0')}</div><h3>${record.kind}</h3><div class="inspector-key-value"><span>时间</span><strong>${record.time}</strong></div><div class="inspector-key-value"><span>来源</span><strong>${esc(record.peer)}</strong></div><div class="inspector-key-value"><span>原始长度</span><strong>${number(record.length)} B</strong></div><div class="hex-header"><span>OFFSET / HEX</span><button class="icon-button" id="copy-bytes" aria-label="复制选中记录的 HEX 字节">${icon('copy')}</button></div><div class="hex-dump">${rows.join('')}</div><div class="byte-legend"><span><i class="legend-square"></i>前 4 字节</span><span>显示 ${bytes.length} / ${record.length} B</span></div><div class="hex-header">ASCII</div><div class="ascii-dump">${esc(ascii(bytes))}</div><p class="detail-note">${current().type==='udp'?'保留 UDP 数据报边界。测试序号为原型模拟规则。':'这是一次字节流读取结果，不代表完整业务帧。'}</p></div>`;
}
function renderDiagnostics(){const udp=current().type==='udp';const rows=[['测试发送端',udp?number(stats.received+Math.max(0,stats.missing-stats.discarded)):'未提供','来自模拟测试序号；真实设备需提供对应计数'],['应用接收',udp?number(stats.received):'字节流接收','仅表示数据已到达应用接收入口'],['应用队列丢弃',number(stats.discarded),stats.discarded?'模拟应用处理不足，队列饱和':'不包括网卡或内核队列丢失'],['原始记录失败',number(stats.recordLost),recording?'正在模拟记录原始数据': '记录未开启，此项不代表记录完整'],['显示抽样 / 暂停',pause?number(pauseSkipped)+' 条':'主动抽样','未展示的数据不计为接收丢包'],['网卡 / 内核丢失','未知','当前原型没有系统级统计，不以零替代未知']];
  $('#diagnostics-view').innerHTML=`<div class="diagnostics-intro"><div><h2>沿数据路径检查丢失</h2><p>${udp?'测试协议序号分析已启用 · 有限观察窗口后判定缺失':'当前未配置业务序号分析，无法判断端到端缺帧'}</p></div><span class="small-label">SIMULATED</span></div>${rows.map((r,i)=>`<div class="diagnostic-row"><span class="stage-number">0${i+1}</span><div><strong>${r[0]}</strong><small>${r[2]}</small></div><span class="stage-value ${i===2&&stats.discarded?'warning':''}">${r[1]}</span></div>`).join('')}<div class="diagnostic-note">${udp?`测试序号缺失 ${number(stats.missing)} 报文，已排除观察窗口内的乱序。仅凭序号缺口仍不能确定丢失发生在网卡、内核还是应用之前。`:'TCP 的网络重传不会直接表现为应用读取缺帧。需要结合完整字节记录、协议分帧和发送端计数判断。'}</div>`;
}
function renderAll(){renderSessions();renderFields();renderHeading();renderMetrics();renderRecords();validateSend();}
function setCycleControls(running){['send-input','send-format','send-eol','cycle-interval','cycle-count'].forEach(id=>$('#'+id).disabled=running);}
function stopCycle(notify=false){if(cycleTimer){clearInterval(cycleTimer);cycleTimer=null;if(notify)toast('周期发送已停止。');}setCycleControls(false);$('#send-button').classList.remove('running');$('#send-button').innerHTML='发送 '+icon('arrow');}
function stopRecording(notify=false){if(!recording)return;recording=false;captures.unshift({name:`${transportNames[recordOrigin.type]}_${recordOrigin.name}`,time:new Date(recordStarted).toLocaleString('sv-SE'),duration:Math.max(1,Math.round((Date.now()-recordStarted)/1000))+' 秒',size:(recordedBytes/1e9).toFixed(2)+' GB',transport:transportNames[recordOrigin.type],state:'已停止 · 模拟',sample:records.map(r=>({id:r.id,peer:r.peer,payloadHex:hex(r.bytes)}))});if(notify)toast('模拟记录已停止，可在采集文件中查看。');renderCaptures();renderInspector();}
function switchSession(id){if(id===activeId)return;stopCycle();stopRecording();current().connected=false;activeId=id;scenario='normal';$('#demo-scenario').value=scenario;pause=false;pauseSnapshot=[];pauseSkipped=0;updatePauseButton();records=[];selectedId=null;stats.received=0;stats.tx=0;stats.missing=0;stats.discarded=0;stats.recordLost=0;$('#record-filter').value='';renderAll();setPage('workspace');toast('已切换方案；上一连接、周期发送与记录已停止。');}
function validIp(v){const parts=v.split('.');return parts.length===4 && parts.every(p=>/^\d{1,3}$/.test(p)&&Number(p)<=255);}
function validPort(v,allowZero=false){return /^\d+$/.test(v)&&Number(v)>=(allowZero?0:1)&&Number(v)<=65535;}
$('#connection-form').addEventListener('submit',e=>{e.preventDefault();const s=current();if(s.connected){s.connected=false;stopCycle();stopRecording();renderAll();toast(s.type==='udp'?'已解除模拟 UDP 绑定。':'模拟连接已停止。');return;}
  const values=Object.fromEntries(new FormData(e.target));let error='';
  if(s.type==='serial'){if(!values.portName.trim())error='请输入串口设备。';else if(!/^\d+$/.test(values.baud)||Number(values.baud)<1||Number(values.baud)>2147483647)error='波特率应为有效正整数。';}
  else{if(values.local&&!validIp(values.local))error='请输入有效的本地 IPv4 地址。';if(values.localPort&&!validPort(values.localPort,s.type==='udp'))error='本地端口范围为 '+(s.type==='udp'?'0':'1')+'–65535。';if(values.remote && (s.type==='udp'?!validIp(values.remote):!/^(?:[a-zA-Z0-9](?:[a-zA-Z0-9.-]*[a-zA-Z0-9])?)$/.test(values.remote)||(/^\d+(?:\.\d+){3}$/.test(values.remote)&&!validIp(values.remote))))error='请输入有效的目标 '+(s.type==='udp'?'IPv4 地址。':'IP 或域名。');if(values.port&&!validPort(values.port))error='目标端口范围为 1–65535。';}
  if(error){$('#connection-error').textContent=error;return;}Object.assign(s.config,values);if(s.type==='udp'&&s.config.localPort==='0')s.config.localPort='53021';s.connected=true;scenario='normal';$('#demo-scenario').value='normal';records=Array.from({length:8},()=>createRecord(++sequence));selectedId=records[0]?.id;stats.received=0;renderAll();toast('模拟'+stateWord()+'，没有访问真实设备。');
});
$('#connection-fields').addEventListener('change',e=>{if(e.target.id==='client-target'){current().config.target=e.target.value;renderHeading();}});
function payloadResult(){const raw=$('#send-input').value;let bytes;if($('#send-format').value==='hex'){const compact=raw.replace(/\s/g,'');if(!compact.length)return {error:'请输入待发送内容'};if(!/^[0-9a-fA-F]+$/.test(compact))return {error:'HEX 包含非法字符'};if(compact.length%2)return {error:'HEX 必须包含完整字节，当前为奇数位'};bytes=Uint8Array.from(compact.match(/.{2}/g).map(x=>parseInt(x,16)));}else{if(!raw.length)return{error:'请输入待发送内容'};bytes=new TextEncoder().encode(raw);}
  const eol={none:[],cr:[13],lf:[10],crlf:[13,10]}[$('#send-eol').value];return{bytes:new Uint8Array([...bytes,...eol])};}
function validateSend(){const result=payloadResult();$('#send-validation').textContent=result.error||`${result.bytes.length} 字节 · ${$('#send-format').value==='hex'?'HEX 格式有效':'UTF-8 编码'}${$('#send-eol').value!=='none'?' · 含附加换行':''}`;$('#send-validation').classList.toggle('invalid',!!result.error);$('#send-button').disabled=!!result.error||!current().connected;if(result.error&&cycleTimer)stopCycle();return result;}
function sendOnce(){const result=validateSend();if(result.error||!current().connected)return false;const record=createRecord(++sequence,'TX',result.bytes);record.time=timeLabel();records.push(record);if(records.length>80)records.shift();stats.tx+=result.bytes.length;selectedId=record.id;if(pause){pauseSkipped++;renderBanner();}else renderRecords();renderMetrics();return true;}
$('#send-button').addEventListener('click',()=>{if(cycleTimer){stopCycle(true);return;}if($('#cycle-enabled').checked){const interval=Number($('#cycle-interval').value);if(!Number.isFinite(interval)||interval<100||interval>3600000){toast('原型周期范围为 100–3,600,000 ms。');return;}if(!sendOnce())return;const limit=Number($('#cycle-count').value);let sent=1;cycleTimer=setInterval(()=>{if(!sendOnce()){stopCycle();return;}sent++;if(limit>0&&sent>=limit){stopCycle();toast(`模拟周期发送已完成 ${limit} 次。`);}},interval);setCycleControls(true);$('#send-button').classList.add('running');$('#send-button').textContent='停止';toast('模拟周期发送已开始；断开连接时自动停止。');}else if(sendOnce())toast(`模拟发送 ${payloadResult().bytes.length} 字节，未向真实设备发出数据。`);});
$('#cycle-enabled').addEventListener('change',()=>{if(!$('#cycle-enabled').checked)stopCycle();});['send-input','send-format','send-eol'].forEach(id=>$('#'+id).addEventListener('input',validateSend));
function updatePauseButton(){$('#pause-button').setAttribute('aria-label',pause?'恢复显示':'暂停显示');$('#pause-button').title=pause?'恢复显示':'暂停显示，接收与记录继续';$('#pause-button').innerHTML=icon(pause?'play':'pause');}
$('#pause-button').addEventListener('click',()=>{pause=!pause;if(pause){pauseSnapshot=[...records];pauseSkipped=0;}else{toast(`显示已恢复；暂停期间省略 ${pauseSkipped} 条模拟样本。`);pauseSnapshot=[];}updatePauseButton();renderBanner();renderRecords();});
$('#clear-button').addEventListener('click',()=>{records=[];pauseSnapshot=[];selectedId=null;renderRecords();toast('仅清空显示。连接、累计统计与记录状态保持。');});
$('#record-filter').addEventListener('input',renderRecords);
$('#record-body').addEventListener('click',e=>{const row=e.target.closest('[data-record]');if(row){selectedId=Number(row.dataset.record);$('#auto-scroll').checked=false;renderRecords();}});
$('#record-body').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.target.click();}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const rows=$$('[data-record]');const index=rows.indexOf(e.target);rows[Math.max(0,Math.min(rows.length-1,index+(e.key==='ArrowDown'?1:-1)))]?.focus();}});
$('#byte-inspector').addEventListener('click',async e=>{if(e.target.closest('#copy-bytes')){const r=displayed().find(r=>r.id===selectedId)||displayed()[0];if(!r)return;try{await navigator.clipboard.writeText(hex(r.bytes));toast('已复制选中记录的完整模拟字节。');}catch{showDialog('复制原始 HEX',`<p>当前浏览器不允许自动复制，可手动选择下方内容。</p><textarea style="height:150px;border:1px solid var(--line)">${hex(r.bytes)}</textarea>`);}}});
$('#record-button').addEventListener('click',()=>{if(!current().connected)return;if(recording)stopRecording(true);else{recording=true;recordedBytes=0;recordStarted=Date.now();recordOrigin={name:current().name,type:current().type};inspector='capture';renderInspector();toast('模拟二进制记录已开始，不会写入本机目录。');}renderMetrics();renderBanner();});
function renderInspector(){$$('#capture-inspector input,#capture-inspector select').forEach(el=>el.disabled=recording);$('#byte-inspector').hidden=inspector!=='bytes';$('#capture-inspector').hidden=inspector!=='capture';$$('[data-inspector]').forEach(b=>b.classList.toggle('active',b.dataset.inspector===inspector));}
function setPage(next){page=next;$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===next));['workspace','captures','commands'].forEach(p=>$('#'+p+'-page').hidden=p!==next);if(next==='captures')renderCaptures();if(next==='commands')renderCommands();}
function saveDownload(name,content,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export-samples').addEventListener('click',()=>{const data=displayed().map(r=>({id:r.id,time:r.time,direction:r.direction,peer:r.peer,length:r.length,payloadHex:hex(r.bytes)}));saveDownload('PortBridge-demo-samples.json',JSON.stringify({simulated:true,scope:'displayed-samples-only',records:data},null,2));toast('已导出当前模拟显示样本，非完整高速采集。');});
function renderCaptures(){$('#capture-list').innerHTML=captures.map((c,i)=>`<article class="capture-item"><span class="file-icon">BIN</span><div><h3>${esc(c.name)}</h3><p>${esc(c.time)} · ${esc(c.state)}</p><div class="capture-meta"><span>${esc(c.transport)}</span><span>${esc(c.duration)}</span><span>${esc(c.size)}</span><span>原始字节 + 索引</span></div></div><button class="button" data-capture="${i}">${icon('download')}导出模拟样本</button></article>`).join('');}
$('#capture-list').addEventListener('click',e=>{const b=e.target.closest('[data-capture]');if(b){const c=captures[Number(b.dataset.capture)];saveDownload('PortBridge-demo-capture.json',JSON.stringify({simulated:true,description:'小型模拟样本，不代表显示的采集容量',capture:c.name,records:c.sample||records.slice(0,5).map(r=>({id:r.id,payloadHex:hex(r.bytes)}))},null,2));toast('已导出小型模拟采集样本。');}});
function renderCommands(){$('#command-list').innerHTML=commands.map(c=>`<article class="command-item"><span class="file-icon">${esc(c.format.toUpperCase())}</span><div><h3>${esc(c.name)}</h3><p>${c.format==='hex'?'HEX 原始字节':'UTF-8 文本'} · 载入后不会自动发送</p><code>${esc(c.payload)}</code></div><div class="command-actions"><button class="button" data-load-command="${c.id}">载入工作台 ${icon('arrow')}</button><button class="icon-button" data-delete-command="${c.id}" aria-label="删除 ${esc(c.name)}">${icon('trash')}</button></div></article>`).join('');renderQuickCommands();}
function renderQuickCommands(){$('#quick-commands').innerHTML='<span>快捷命令</span>'+commands.slice(0,3).map(c=>`<button class="quick-command" data-load-command="${c.id}">${esc(c.name)}</button>`).join('')+'<span class="quick-hint">点击载入，不自动发送</span>';}
function persistCommands(){try{localStorage.setItem('portbridge-ui-commands',JSON.stringify(commands));}catch{toast('浏览器限制本地保存，本次修改仅在当前页面有效。');}}
function showDialog(title,content){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=content;$('#app-dialog').showModal();}
function commandDialog(){showDialog('添加快捷命令',`<form id="command-form" class="dialog-form"><label>命令名称<input name="name" required maxlength="40" placeholder="例如：读取设备版本"></label><label>发送格式<select name="format"><option value="hex">HEX</option><option value="text">文本 / UTF-8</option></select></label><label>指令内容<textarea name="payload" required spellcheck="false" placeholder="AA 55 01 00"></textarea></label><p id="command-form-error" class="field-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button" data-close-dialog>取消</button><button class="button primary" type="submit">保存命令</button></div></form>`);}
$('#new-session').addEventListener('click',()=>showDialog('新建连接方案',`<form id="new-session-form" class="dialog-form"><label>方案名称<input name="name" required maxlength="30" placeholder="例如：产线设备 01"></label><label>通信类型<select name="type"><option value="serial">串口</option><option value="tcp">TCP 客户端</option><option value="server">TCP 服务端</option><option value="udp">UDP</option></select></label><p class="muted-note">创建后在左侧配置参数；不会自动连接设备。</p><div class="dialog-actions"><button type="button" class="button" data-close-dialog>取消</button><button class="button primary">创建方案</button></div></form>`));
$('#dialog-content').addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(e.target.id==='command-form'){if(!values.name.trim()||!values.payload.trim())return;const compact=values.payload.replace(/\s/g,'');if(values.format==='hex'&&(!/^[0-9a-fA-F]+$/.test(compact)||compact.length%2)){$('#command-form-error').textContent='请输入合法、完整的 HEX 字节。';return;}commands.push({id:Math.max(0,...commands.map(c=>Number(c.id)||0))+1,name:values.name.trim(),payload:values.payload,format:values.format});persistCommands();renderCommands();$('#app-dialog').close();toast('快捷命令已保存。');}else if(e.target.id==='new-session-form'){if(!values.name.trim())return;const template=sessions.find(s=>s.type===values.type);const newId='session-'+Date.now();sessions.push({...template,id:newId,name:values.name.trim(),config:{...template.config},connected:false});$('#app-dialog').close();switchSession(newId);}});
$('#dialog-content').addEventListener('click',e=>{if(e.target.closest('[data-close-dialog]'))$('#app-dialog').close();});$('#dialog-close').addEventListener('click',()=>$('#app-dialog').close());
$('#app-dialog').addEventListener('click',e=>{if(e.target===$('#app-dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)e.target.close();}});
$('#add-command').addEventListener('click',commandDialog);$('#open-command-library').addEventListener('click',()=>setPage('commands'));
$('#help-button').addEventListener('click',()=>showDialog('PortBridge 界面原型',`<div class="help-content"><p>这是用于评审布局与交互的桌面应用原型。所有设备、流量、吞吐、丢失和磁盘数据均为模拟，不会连接串口、发送网络报文或写入显示的采集目录。</p><ul><li>左侧切换四种连接方案，参数可在断开后编辑。</li><li>普通 / 高速模式、数据 / 诊断、字节 / 采集设置均可切换。</li><li>底部“原型场景”模拟过载、记录变慢和连接中断。</li><li>支持命令编辑、HEX 校验、周期发送和样本下载。</li></ul><p>参考交互结构：</p><a href="https://www.wireshark.org/docs/wsug_html_chunked/ChUseMainWindowSection.html" target="_blank" rel="noreferrer">Wireshark</a> · <a href="https://www.saleae.com/support/logic-software" target="_blank" rel="noreferrer">Saleae Logic</a> · <a href="https://serial-studio.com/help/protocol-setup-guides" target="_blank" rel="noreferrer">Serial Studio</a></div>`));
$('#theme-button').addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('portbridge-ui-theme',theme);}catch{}});try{const theme=localStorage.getItem('portbridge-ui-theme');if(['light','dark'].includes(theme))document.documentElement.dataset.theme=theme;}catch{}
$('#sidebar-toggle').addEventListener('click',()=>$('#connection-sidebar').classList.toggle('open'));
$('#demo-scenario').addEventListener('change',e=>{scenario=e.target.value;stats.discarded=scenario==='overload'?2048:0;stats.missing=current().type==='udp'?(scenario==='overload'?2176:128):0;if(scenario==='disconnected'){current().connected=false;stopCycle();stopRecording();}else if(!current().connected){current().connected=true;toast('已恢复模拟连接。');}renderAll();renderInspector();});
document.addEventListener('click',e=>{const session=e.target.closest('[data-session]');if(session){switchSession(session.dataset.session);return;}const p=e.target.closest('[data-page]');if(p){setPage(p.dataset.page);return;}const m=e.target.closest('[data-mode]');if(m){current().mode=m.dataset.mode;renderHeading();renderMetrics();toast(m.dataset.mode==='high'?'高速模式：显示抽样，原始接收独立运行。':'普通模式：详细观察当前模拟收发记录。');return;}const v=e.target.closest('[data-view]');if(v){view=v.dataset.view;$('#data-view').hidden=view!=='data';$('#diagnostics-view').hidden=view!=='diagnostics';$$('[data-view]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.view===view)));renderDiagnostics();return;}const f=e.target.closest('[data-format]');if(f){displayFormat=f.dataset.format;$$('[data-format]').forEach(b=>b.classList.toggle('active',b.dataset.format===displayFormat));renderRecords();return;}const ins=e.target.closest('[data-inspector]');if(ins){inspector=ins.dataset.inspector;renderInspector();return;}const load=e.target.closest('[data-load-command]');if(load){const c=commands.find(c=>c.id===Number(load.dataset.loadCommand));if(!c)return;stopCycle();$('#send-input').value=c.payload;$('#send-format').value=c.format;$('#send-eol').value='none';validateSend();setPage('workspace');$('#send-input').focus();toast('指令已载入，请检查后主动发送。');return;}const del=e.target.closest('[data-delete-command]');if(del){commands=commands.filter(c=>c.id!==Number(del.dataset.deleteCommand));persistCommands();renderCommands();toast('命令已从原型命令库删除。');}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setPage('workspace');$('#record-filter').focus();}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&page==='workspace'&&!$('#app-dialog').open){e.preventDefault();$('#send-button').click();}if(e.key==='Escape')$('#connection-sidebar').classList.remove('open');});
setInterval(()=>{if(!current().connected)return;const rate=currentRate();stats.received+=current().type==='udp'?Math.round(rate*1e6/1472*1.5):Math.round(rate*1e6*1.5);if(recording)recordedBytes+=rate*1e6*1.5;const row=createRecord(++sequence);row.time=timeLabel();records.push(row);if(records.length>80)records.shift();if(pause)pauseSkipped++;if(page==='workspace'){renderMetrics();renderBanner();if(!pause)renderRecords();}},1500);
renderAll();renderQuickCommands();renderInspector();renderCaptures();
